jQuery(document).ready(function(){
  jQuery('.acc-head').click(function(){
    jQuery(this).next().slideToggle(500);
    jQuery(this).toggleClass('active');
  })
})

jQuery(document).ready(function(e) {



// TOOLTIP
jQuery("[data-toggle='tooltip']").tooltip();
 
 //EQUEL-HEIGHT
 
jQuery(".matchHeight").matchHeight(); 
       
       
 jQuery('no').click(function() {
    if (location.pathname.replace(/^\//,'') == this.pathname.replace(/^\//,'') && location.hostname == this.hostname) {
      var target = jQuery(this.hash);
      target = target.length ? target : jQuery('[name=' + this.hash.slice(1) +']');
      if (target.length) {
        jQuery('html, body').animate({
          scrollTop: target.offset().top
        }, 1000);
        return false;
      }
    }
  });
  
//scroll top

jQuery(window).scroll(function(){
        if (jQuery(this).scrollTop()>100){
            jQuery(".scrollup").addClass("active");
        }else{
            jQuery(".scrollup").removeClass("active");
        }
    });
    jQuery(".scrollup").click(function(){
        jQuery("html, body").animate({scrollTop:0},600);
        return false;
    });
    
//scroll top

 jQuery(".content").slice(0, 6).show();
  jQuery("#loadMore").on("click", function(e){
    e.preventDefault();
    jQuery(".content:hidden").slice(0, 6).slideDown();
    if(jQuery(".content:hidden").length == 0) {
      jQuery("#loadMore").text("No Product").addClass("noContent");
    }
  });



jQuery(".slider-team").owlCarousel({
loop:true,

autoplay:false,
    margin:30,
    items:3,
     nav: true,
  dots: false,
navText: ['<span class="fa fa-arrow-left"></span>','<span class="fa fa-arrow-right"></span>'],
    responsive:{
        0:{
            items:1
        },
        600:{
            items:3
        }
    }
 
});

jQuery(".slider-brand").owlCarousel({
loop:true,

autoplay:false,
    margin:30,
    items:6,
     nav: false,
  dots: true,
    responsive:{
        0:{
            items:1
        },
        600:{
            items:3
        },
        1000:{
            items:6
        }
    }
 
});
// slick slider



jQuery('.slider').slick({
  autoplay: false,
  fade: false,
  speed: 800,
  lazyLoad: 'progressive',
  arrows: false,
  dots: true,
  appendDots: jQuery('.slick-slider-dots'),
  cssEase: 'ease-in-out',
    touchThreshold: 100,
}).slickAnimation();



jQuery('.slick-client').slick({
  infinite: true,
  slidesToShow: 1, // Shows a three slides at a time
  slidesToScroll: 1, // When you click an arrow, it scrolls 1 slide at a time
  arrows: false, // Adds arrows to sides of slider
  dots: false // Adds the dots on the bottom
});

var slider = jQuery('.slick-client');

jQuery('.prev').click(function(){
    slider.slick('slickPrev');
    return false;
});

jQuery('.next').click(function(){
    slider.slick('slickNext');
    return false;
});




});




// STYCK JS
jQuery(window).scroll(function() {
if (jQuery(this).scrollTop() > 1){  
    jQuery('.top-head').addClass("sticky");
  }
  else{
    jQuery('.top-head').removeClass("sticky");
  }
});
// STYCK JS END



